#ifndef TMCRULESREPO_H
#define TMCRULESREPO_H

#include <QHash>
#include <QString>
#include <QVariantMap>
#include <QVector>

// The v2.0 rules catalog: rules/<layer>.json, one descriptor per object code (the file list and
// the enumeration order are hardcoded below — the exporter styles are per layer, only codes may
// be added). This class is the single reader: it answers "what does this code mean on this layer"
// (height chain, effect, model, layer meta). Generated by devtools/make_rules.py — the loader
// never writes.
class TmcRulesRepo
{
public:
    enum Family { FamilyPoly, FamilyLine, FamilyPoint };         // by the layer geometry
    enum RelMode { RelNone, RelAuto, RelFixed };                 // height: none / column->default / strict value

    struct Object
    {
        QString uid;                       // globally unique, survives regeneration
        int code = 0;                      // the 8-digit code assigned by an osm rule
        QString name;                      // display name (GUI, logs)
        QString effect;                    // "" / "swamp" / "prison" / "military"
        int model = 0;                     // the family enum value (ModelPoint/ModelPoly/ModelLine)
        RelMode relMode = RelNone;
        QString relColumn;                 // RelAuto: the data column carrying meters
        double relDefault = 0.0;           // RelAuto: fallback height, meters (only with relHasDefault)
        bool relHasDefault = false;        // the code is described with an explicit Default (a zero is a height too)
        double relValue = 0.0;             // RelFixed: strict height, meters
        bool internal = false;             // synthesized by the exporter, absent in the input data
        QVariantMap props;                 // layer-specific: WidthScale, Marking, ...
    };

    struct Layer
    {
        QString name;
        Family family = FamilyPoly;
        double widthBase = 0.0;            // line layers: the base line width in meters
        QString materialColumn;            // "MAT" for bldpol, empty elsewhere
        bool dbCodes = false;              // bldpol: codes from the building database pass through
        bool heightColumn = false;         // some code reads Rel from a column: the layer extrudes by height
        QVector<Object> objects;
        QHash<int, int> byCode;            // code -> index in objects
    };

    static TmcRulesRepo& instance();

    // Reads every layer file of the catalog. Fails if a known layer file is missing or unreadable
    // (a half catalog misplaces objects); unknown json files and unknown keys only warn.
    bool load(const QString& rulesDir, QString* err, QStringList* warnings = nullptr);
    bool isLoaded() const { return !order_.isEmpty(); }
    QString dir() const { return dir_; }

    // The layer enumeration order (the old .t3d source order: milpol+pripol merged into terpol
    // at the pripol place, vgbpol last) — the pipeline must iterate exactly this to keep the
    // generation deterministic (the object order feeds the seeded decisions of the export).
    const QStringList& order() const { return order_; }
    const Layer* layer(const QString& name) const;
    const Object* object(const QString& layerName, int code) const;
    const Object* objectByCode(int code) const;              // codes are catalog-unique

    static double widthScale(const Object& o) { return o.props.value(QStringLiteral("WidthScale"), 1.0).toDouble(); }
    static bool marking(const Object& o) { return o.props.value(QStringLiteral("Marking")).toBool(); }

    // The catalog folder: an explicit --rules path, then <exe>/rules, then <cwd>/rules, then the
    // hint folder (its own rules/ subfolder first) — whichever contains the layer files. Empty when nothing found.
    static QString discover(const QString& explicitDir = QString(), const QString& hintDir = QString());

private:
    TmcRulesRepo() = default;

    QVector<Layer> layers_;
    QHash<QString, int> byName_;
    QStringList order_;                                      // enumerated layer names
    QHash<int, const Object*> byCode_;                       // first layer wins on a clash
    QString dir_;
};

#endif   // TMCRULESREPO_H
